import { CertificateServices } from '../../services/certificateServices.js';
import Boom from '@hapi/boom';

/**
 * Controller function to create a new certificate covering ONE OR MORE
 * enrollments. The official act number is auto-generated by
 * CertificateServices in the format 'YY-NNN' (e.g. '26-001').
 *
 * The service links every id in `enrollmentIds` to the newly created
 * certificate row through the bridge table 'certificado_matricula',
 * inside a single transaction — so either the whole group is
 * committed or nothing is. That is how a single act number ends up
 * owning N enrollments and can drive a single multi-enrollment PDF.
 *
 * The rotated JWT is not signed here: authAppVerifyToken already
 * generated it upstream, wrote it to the httpOnly 'authentication'
 * cookie, and exposed the same value via res.locals.newUserToken.
 *
 * @param {Object} req - The Express request object.
 * @param {Object} req.body - The validated request body (see certificateSchema.newCertificateData).
 * @param {string} req.body.issueDate - Certificate issue date.
 * @param {string|number} req.body.userId - Issuing user id.
 * @param {string|number} req.body.institutionId - Institution id.
 * @param {Array<string|number>} req.body.enrollmentIds - One or more enrollment ids.
 * @param {string|number} [req.body.recipientId] - Optional recipient id.
 * @param {string} [req.body.status] - Optional status; defaults to 'EMITIDO'.
 * @param {Object} res - The Express response object.
 * @param {string} res.locals.newUserToken - The rotated JWT set by authAppVerifyToken.
 * @param {Function} next - The next middleware function in the Express.js stack.
 * @returns {Promise<void>}
 */
export const createOneCertificate = async (req, res, next) => {
  const newCertificate = {
    issueDate: req.body.issueDate,
    userId: req.body.userId,
    institutionId: req.body.institutionId,
    // Array of enrollment ids — one certificate, many enrollments
    enrollmentIds: req.body.enrollmentIds,
    recipientId: req.body.recipientId,
    status: req.body.status,
  };

  const certificateManager = new CertificateServices();

  try {
    const response = await certificateManager.createOne(newCertificate);

    if (response.status === 'CREATED SUCCESSFULLY') {
      return res.status(201).json({
        success: true,
        message: 'Certificado creado exitosamente',
        actNumber: response.actNumber,
        // Echo back exactly which enrollments were linked, so the
        // client can immediately build the multi-enrollment PDF.
        enrollmentIds: response.enrollmentIds,
        authentication: res.locals.newUserToken,
      });
    }
  } catch (error) {
    const boomError = Boom.boomify(error, {
      message: 'No es posible crear el certificado en la base de datos',
    });
    next(boomError);
  }
};
